  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Loxapine, the closest structural analogue (dibenzoxazepine with Cl and N-methylpiperazine), has a human systemic availability of 0.29 (29%), above the 20% threshold despite high hepatic extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Prochlorperazine, a tricyclic neuroleptic with Cl and a basic amine, has absolute oral bioavailability of 12.5% in healthy volunteers, below the threshold; this is the main contradictory example but is less structurally similar to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Clomipramine, a chlorinated tricyclic antidepressant with a basic side chain, has mean absolute bioavailability of 48% (range 36-68%) in healthy volunteers, supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Mirtazapine, a tetracyclic antidepressant with a fused N-methylpiperazine, has absolute bioavailability of 49.7±9.8% in healthy volunteers, supporting high F for rigid polycyclic basic amines.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high because the closest analogue loxapine has F=29% (above 20%) and most tricyclic/tetracyclic CNS drugs with similar features show F≥48%; the only low example (prochlorperazine) is less structurally similar and its extensive first-pass metabolism is not clearly shared by the query.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "The closest analogue loxapine has F=29%, close to the 20% threshold, so small metabolic differences could shift the classification.",
    "The query's pyrrolidine-fused dibenzoxepine scaffold is not identical to any evidence molecule; transferability from piperazine/imine-containing analogues is imperfect.",
    "Prochlorperazine demonstrates that some tricyclic neuroleptics undergo extensive first-pass metabolism, but its lower similarity limits weight."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

